const names=["viewer-part-00.txt", "viewer-part-01.txt", "viewer-part-02.txt", "viewer-part-03.txt", "viewer-part-04.txt", "viewer-part-05.txt", "viewer-part-06.txt", "viewer-part-07.txt", "viewer-part-08.txt", "viewer-part-09.txt", "viewer-part-10.txt"];
const parts=await Promise.all(names.map(async name=>{const r=await fetch(new URL(name,import.meta.url));if(!r.ok)throw new Error("Viewer part failed: "+r.status);return r.text()}));
await import(URL.createObjectURL(new Blob([parts.join("")],{type:"application/javascript"})));
